FTG.CATEGORY_LABELS = {
  bread: ['Leipä ja leivonnaiset', 'Bread & pastries'],
  produce: ['Hedelmät ja vihannekset', 'Fruit & vegetables'],
  dairy: ['Maitotuotteet', 'Dairy'],
  meals: ['Valmisruoat', 'Prepared meals'],
  meat: ['Liha', 'Meat'],
  fish: ['Kala', 'Fish'],
  dry: ['Kuiva- ja säilyketuotteet', 'Dry goods & cans'],
  snacks: ['Välipalat ja makeiset', 'Snacks & sweets'],
  other: ['Muu', 'Other'],
};

FTG.lang = 0; // 0 = fi, 1 = en
FTG.t = function (key, vars) {
  const entry = FTG.STRINGS[key];
  let s = entry ? (entry[FTG.lang] || entry[0]) : key;
  if (vars) for (const k in vars) s = s.split('{' + k + '}').join(vars[k]);
  return s;
};
FTG.cat = function (key) { const e = FTG.CATEGORY_LABELS[key]; return e ? e[FTG.lang] : key; };
